// Structured logging + manual span timing (Node.js — no SDK required)
import { randomUUID } from 'crypto';

// ── Structured logger ─────────────────────────────────────────
// Every line includes traceId so you can grep one ID across services
function log(level, event, fields = {}) {
  const entry = {
    timestamp: new Date().toISOString(),
    level,
    event,
    ...fields,
  };
  process.stdout.write(JSON.stringify(entry) + '\n');
}

// ── Span wrapper ──────────────────────────────────────────────
// In production, replace this with the OpenTelemetry Node.js SDK.
// This version shows the core idea without dependencies.
async function withSpan(spanName, traceId, parentSpanId, fn) {
  const spanId = randomUUID();
  const start = Date.now();
  log('DEBUG', 'span.start', { spanName, traceId, spanId, parentSpanId });
  try {
    const result = await fn({ traceId, spanId });
    log('INFO', 'span.end', {
      spanName, traceId, spanId,
      durationMs: Date.now() - start,
      ok: true,
    });
    return result;
  } catch (err) {
    log('ERROR', 'span.error', {
      spanName, traceId, spanId,
      durationMs: Date.now() - start,
      error: err.message,
      stack: err.stack,
    });
    throw err;
  }
}

// ── HTTP handler ──────────────────────────────────────────────
export async function createOrderHandler(req, res) {
  // Accept trace ID from upstream (gateway / client) or generate new one
  const traceId = req.headers['traceparent'] ??
                  req.headers['x-trace-id'] ??
                  randomUUID();
  // Echo it back so client can correlate with its own logs
  res.setHeader('x-trace-id', traceId);

  try {
    const order = await withSpan('createOrder', traceId, null, async ({ spanId }) => {
      // Validate input — child span
      await withSpan('validateInput', traceId, spanId,
        async () => validateOrderInput(req.body));

      // Call payment service — child span, passes traceId in outbound header
      const payment = await withSpan('chargePayment', traceId, spanId,
        async () => paymentClient.charge(req.body.amount, {
          headers: { 'x-trace-id': traceId }, // context propagation!
        }));

      // Persist — child span
      return withSpan('insertOrder', traceId, spanId,
        async () => orderRepo.insert({ ...req.body, paymentId: payment.id }));
    });

    log('INFO', 'order.created', { traceId, orderId: order.id, userId: req.user.id });
    res.status(201).json(order);
  } catch (err) {
    log('ERROR', 'order.failed', {
      traceId,
      error: err.message,
      userId: req.user?.id,
    });
    res.status(500).json({ error: 'Order creation failed' });
  }
}
